// STORE - the ONE Redux Toolkit store of the app.
//
// It is built from:
//   auth      - who is logged in + Parent PIN, from the backend (app/store/authSlice.js)
//   child     - the child profiles + Parent/Child mode   (app/store/childSlice.js)
//   preview   - the Explore KidBuddy switch, nothing is saved (app/store/previewSlice.js)
//   <module>  - one slice per learning module            (english, later numbers, feelings ...)
//
// You do NOT edit this file to add a module: add it to src/modules/index.js and its
// reducer is picked up here automatically.
//
// Which tool for what?
//   Redux Toolkit - data that screens read and change: child profiles, the Read Along
//                   topic / level, struggle words ...
//   authSlice     - who is logged in, the Parent PIN (data from the backend). Screens use it
//                   through useAuth() in app/context/AuthContext.js.
//   Language / Device context - language and phone settings, also needed by the whole app.

import { configureStore, createListenerMiddleware } from '@reduxjs/toolkit';
import authReducer from './authSlice';
import childReducer, { selectChild } from './childSlice';
import previewReducer from './previewSlice';
import { MODULES } from '../../modules';

// { auth: ..., child: ..., english: ..., numbers: ... }
const reducers = { auth: authReducer, child: childReducer, preview: previewReducer };
MODULES.forEach((module) => {
  if (module.reducer) reducers[module.name] = module.reducer;
  if (module.reducers) Object.assign(reducers, module.reducers); // extra slices, e.g. englishAlphabet
});

// A LISTENER waits for one action and then runs some code.
// Here: when "Continue as Zara" worked (selectChild.fulfilled), every module that wants to
// can load its data for that child (the English module loads its reading topics).
const listener = createListenerMiddleware();
listener.startListening({
  actionCreator: selectChild.fulfilled,
  effect: (action, listenerApi) => {
    const childId = action.payload.activeId;
    MODULES.forEach((module) => {
      if (module.onChildSelected) listenerApi.dispatch(module.onChildSelected(childId));
    });
  },
});

export const store = configureStore({
  reducer: reducers,
  middleware: (getDefaultMiddleware) => getDefaultMiddleware().prepend(listener.middleware),
});

// Some modules need to read their saved data when the app starts.
MODULES.forEach((module) => {
  if (module.load) store.dispatch(module.load());
});
